using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Non-static class — services are injected via the constructor.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID (1-100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts to this user ID (omit for all posts)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var path = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var json = await client.GetStringAsync(path, cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
        return json;
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Search posts by title substring (case-insensitive).")]
    public async Task<string> SearchPosts(
        [Description("Text to search for in post titles")] string query,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var json = await client.GetStringAsync("/posts", cancellationToken);
        var posts = JsonSerializer.Deserialize<JsonElement>(json);

        var matches = posts.EnumerateArray()
            .Where(p => p.GetProperty("title").GetString()!
                .Contains(query, StringComparison.OrdinalIgnoreCase))
            .ToList();

        return JsonSerializer.Serialize(matches, JsonOptions);
    }
}

